(* [comment removed for export] *)
Definition csr_keeps (op : csrop) (operand : word) (writes : bool) (csr : bv 12) : bool :=
  negb writes || negb (csr_frmw csr) ||
  match op with
  | CSR_RC => true
  | _ => if bv_unsigned csr =? 3 then bv_unsigned operand <? 32 else Z.land (bv_unsigned operand) 7 =? 0
  end.

