(* [comment removed for export] *)
Ltac csr_keeps_tac Hs :=
  unfold csr_keeps; destruct (csr_frmw _) eqn:CF; cbn [negb orb] in Hs |- *;
  rewrite ?orb_true_r; try reflexivity; try discriminate;
  try (rewrite Hs; reflexivity);
  try (match goal with |- context [bv_unsigned ?c =? 3] =>
         case_eq (bv_unsigned c =? 3); intros E3; rewrite E3 in *; cbn [orb] in Hs |- * end;
       [ rewrite (proj2 (Z.ltb_lt _ _) (zext5_lt32 _)); rewrite ?orb_true_r; reflexivity
       | rewrite zext5_land7, Hs; rewrite ?orb_true_r; reflexivity ]).

